#ifndef EMU_FONT_H
#define EMU_FONT_H

#include <stdint.h>

/* Bitmap fonts for the OS text syscalls (font_data.c, generated by
 * tools/gen_fonts.py). Each glyph is a cell of the font's height and w
 * pixels, rows of (w + 7) / 8 bytes, most significant bit first. left and
 * adv place it in proportional text: its first lit column and its width
 * plus 1 px of spacing. */
typedef struct {
    uint32_t cp;      /* Unicode code point */
    uint32_t offset;  /* into the font's bits */
    uint8_t w, left, adv;
} FontGlyph;

typedef struct Font {
    uint8_t h;
    uint16_t count;
    const FontGlyph *glyphs; /* sorted by cp */
    const uint8_t *bits;
} Font;

extern const Font FONT_BIG;   /* Spleen 12x24: PrintXY, PrintCXY, line editing */
extern const Font FONT_MINI;  /* Spleen 8x16: PrintMini, Bdisp_MMPrint */
extern const Font FONT_TINY;  /* Spleen 5x8: PrintMiniMini */
extern const Font FONT_EXTRA; /* GNU Unifont 8x16 / 16x16 symbols the others lack */

/* The glyph for cp, or NULL. */
const FontGlyph *font_glyph(const Font *font, uint32_t cp);

#endif
